fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Construct the first output matrix:
    // Each row is a clone of the entire x vector.
    let grid_x = vec![x.clone(); rows];

    // Construct the second output matrix:
    // Each row has the same value y[i], repeated cols times.
    let grid_y = y
        .into_iter()
        .map(|yi| vec![yi; cols])
        .collect::<Vec<Vec<f32>>>();

    (grid_x, grid_y)
}